import threading

class CapLog:
    def __init__(self):
        self.records = []
        self._lock = threading.Lock()

    def handle(self, record):
        with self._lock:
            self.records.append(record)

    @property
    def text(self):
        with self._lock:
            return "\n".join(str(r) for r in self.records)

