import unittest
from pytest_logging.caplog import CapLog

class TestCapLog(unittest.TestCase):
    def test_thread_safe_log(self):
        cap = CapLog()
        cap.handle("msg 1")
        cap.handle("msg 2")
        self.assertEqual(cap.text, "msg 1\nmsg 2")

if __name__ == '__main__': unittest.main()
